#ifndefFGOUTPUTTYPE_H
#defineFGOUTPUTTYPE_H

/*%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
INCLUDES
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%*/

#include<memory>

#include"models/FGModel.h"

/*%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
FORWARDDECLARATIONS
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%*/

namespaceJSBSim{

classFGFDMExec;
classElement;
classFGAerodynamics;
classFGAuxiliary;
classFGAircraft;
classFGWinds;
classFGPropulsion;
classFGMassBalance;
classFGPropagate;
classFGAccelerations;
classFGFCS;
classFGGroundReactions;
classFGExternalReactions;
classFGBuoyantForces;
classFGPropertyValue;

/*%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
CLASSDOCUMENTATION
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%*/

/*%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
CLASSDECLARATION
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%*/

classFGOutputType:publicFGModel
{
public:
FGOutputType(FGFDMExec*fdmex);

~FGOutputType()override;

voidSetIdx(unsignedintidx);

voidSetRateHz(doublertHz);

doubleGetRateHz(void)const;

voidSetSubSystems(intsubSystems){SubSystems=subSystems;}

voidSetOutputProperties(std::vector<SGPropertyNode_ptr>&outputProperties);

virtualvoidSetOutputName(conststd::string&name){Name=name;}

virtualconststd::string&GetOutputName(void)const{returnName;}

boolLoad(Element*el)override;

boolInitModel(void)override;

boolRun(boolHolding)override;

virtualvoidPrint(void)=0;

virtualvoidSetStartNewOutput(void){}

voidEnable(void){enabled=true;}
voidDisable(void){enabled=false;}
boolToggle(void){enabled=!enabled;returnenabled;}

enumeSubSystems{
ssSimulation=1,ssAerosurfaces=2,ssRates=4,ssVelocities=8,ssForces=16,ssMoments=32,ssAtmosphere=64,ssMassProps=128,ssAeroFunctions=256,ssPropagate=512,ssGroundReactions=1024,ssFCS=2048,ssPropulsion=4096}subsystems;

protected:
unsignedintOutputIdx;
intSubSystems;
std::vector<FGPropertyValue*>OutputParameters;
std::vector<std::string>OutputCaptions;

std::shared_ptr<FGAerodynamics>Aerodynamics;
std::shared_ptr<FGAuxiliary>Auxiliary;
std::shared_ptr<FGAircraft>Aircraft;
std::shared_ptr<FGWinds>Winds;
std::shared_ptr<FGPropulsion>Propulsion;
std::shared_ptr<FGMassBalance>MassBalance;
std::shared_ptr<FGPropagate>Propagate;
std::shared_ptr<FGAccelerations>Accelerations;
std::shared_ptr<FGFCS>FCS;
std::shared_ptr<FGGroundReactions>GroundReactions;
std::shared_ptr<FGExternalReactions>ExternalReactions;
std::shared_ptr<FGBuoyantForces>BuoyantForces;

voidDebug(intfrom)override;
};
}
//%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
#endif
